INSERT INTO public.locations (region_id, type, name, address_line1, city_or_regency, province, country_code)
SELECT r.id, s.type, s.name, s.address_line1, s.city_or_regency, s.province, s.country_code
FROM seed_locations s
JOIN public.regions r ON r.code = s.region_code
WHERE NOT EXISTS (
    SELECT 1
    FROM public.locations l
    WHERE l.type = s.type
      AND l.name = s.name
      AND l.city_or_regency = s.city_or_regency
      AND l.province = s.province
);

COMMIT;